import{z as i,x as d,o as E,c as l,q as t,j as r,D as e,d as B,s as A,S as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"深度对冲的深化","description":"","frontmatter":{"title":"深度对冲的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dp-deep-hedging-deep.md","filePath":"quant/dp-deep-hedging-deep.md","lastUpdated":1791413859000}'),s={name:"quant/dp-deep-hedging-deep.md"};function h(p,a,u,D,m,_){const n=d("Mermaid");return E(),l("div",null,[a[2]||(a[2]=t('<h1 id="深度对冲的深化" tabindex="-1">深度对冲的深化 <a class="header-anchor" href="#深度对冲的深化" aria-label="Permalink to &quot;深度对冲的深化&quot;">​</a></h1><div class="epigraph"><p>骨架课把对冲写成风险度量下的策略学习；深化回答的是账本问题：对冲整本奇异用哪些工具、风险度量是谁的产品、模拟器的小数据降维丢了什么——每一问都把模拟器重新推到台前。</p><footer>—— 据 Buehler, Gonon, Teichmann and Wood, Quantitative Finance, 2019；Buehler, Horvath, Lyons, Perez Arribas and Wood, 2020 整理</footer></div><p><a href="/quant/dp-generative-calibration">上一课</a>把生成模型收成可冻结交付的模拟器，末尾留了一句警告：下游网络会把伪影当 alpha。本课就是那个下游。<a href="/quant/deep-hedging-buehler">Deep Hedging</a> 已立好骨架：凸风险度量下训练策略网络、库存进状态、摩擦进环境，与解倒向方程的 <a href="/quant/deep-bsde">Deep BSDE</a> 分工。本课做深化：从单一支付走到整本账，从单一工具走到对冲工具集的选择，从「给定 \\(\\rho\\)」走到「\\(\\rho\\) 是产品参数」，以及模拟器本身的小数据问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>柜台的现实不是「对冲一个看涨」：一本账里有自动赎回、障碍、亚式，对冲工具是有限的香草与期货。经典做法把账拆进<a href="/quant/greeks-hedge">希腊</a>桶——vega 分档、vanna 与 charm 单列（<a href="/quant/vanna-volga">vanna-volga</a> 的启发式）、黏性 delta 换算（<a href="/quant/sticky-delta-strike">黏性 delta</a>）——再把每桶分给交易台。深度对冲的深化问题不是推翻这套，而是问它切断了哪些耦合：一篮子障碍在同一波动跳动下的联合暴露，桶加和覆盖不了；对冲工具集的选择——用哪些期限的香草、要不要用期货替代——本来是离散决策，桶方法里被默认固化。策略网络把这些重新连起来，代价是全部压在模拟器与 \\(\\rho\\) 的选择上。</p><p><span class="marginnote">术语翻译：「桶方法」就是把账本风险按希腊字母分桶管理——delta 一桶、vega 一桶、vanna 一桶，各交给一个交易台分别对冲；盲区在桶与桶的耦合，比如一次波动跳动同时扫到一篮子障碍的联合暴露，分桶加和看不见。</span></p><h3 id="风险度量是产品参数" tabindex="-1">风险度量是产品参数 <a class="header-anchor" href="#风险度量是产品参数" aria-label="Permalink to &quot;风险度量是产品参数&quot;">​</a></h3><p>CVaR 的 \\(\\alpha\\) 与熵风险的 \\(\\eta\\) 决定网络在尾部情景付多少成本去救：CVaR 只看最差层的平均，网络会放弃躯干去保尾部；熵风险平滑但重罚极端路径。它们不是优化器超参，是销售与资本口径的产品定义——同一个网络结构、不同 \\(\\rho\\)，就是不同的产品，历史残差不可比。</p><p>两种常用风险度量把同一张 PnL 分布读成两种产品：</p>',9)),(E(),r(o,null,{default:e(()=>[A(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E9%80%89%E5%93%AA%E4%B8%AA%E9%A3%8E%E9%99%A9%E5%BA%A6%E9%87%8F%20%CF%81%3F%22%5D%20--%3E%20CVaR%5B%22CVaR%3A%20%E5%8F%AA%E7%9C%8B%E6%9C%80%E5%B7%AE%20%CE%B1%20%E5%B1%82%E7%9A%84%E5%B9%B3%E5%9D%87%22%5D%0A%20%20Q%20--%3E%20Ent%5B%22%E7%86%B5%E9%A3%8E%E9%99%A9%3A%20%E6%8C%87%E6%95%B0%E5%8A%A0%E6%9D%83%E6%95%B4%E6%9D%A1%E5%88%86%E5%B8%83%22%5D%0A%20%20CVaR%20--%3E%20C1%5B%22%E8%BA%AF%E5%B9%B2%E5%8F%AF%E6%94%BE%E5%BC%83%2C%20%E4%BF%9D%E5%B0%BE%E9%83%A8%E6%9B%B4%E7%8B%A0%22%5D%0A%20%20Ent%20--%3E%20E1%5B%22%E5%B9%B3%E6%BB%91%2C%20%E4%BD%86%E6%9E%81%E7%AB%AF%E8%B7%AF%E5%BE%84%E8%A2%AB%E9%87%8D%E7%BD%9A%22%5D%0A%20%20C1%20--%3E%20Same%5B%22%E5%90%8C%E4%B8%80%E7%BD%91%E7%BB%9C%2C%20%E6%8D%A2%20%CF%81%20%E5%8D%B3%E6%8D%A2%E4%BA%A7%E5%93%81%22%5D%0A%20%20E1%20--%3E%20Same%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">数字实例：评估对冲误差不看均值而看分布——例如报告 PnL 的 5% 分位从 −2.0 改善到 −1.4、99% 分位从 −5.0 收窄到 −3.5；若只有均值从 −0.30 变到 −0.25 而尾部纹丝不动，多半是省了事、没救险。</span></p><p><span class="marginnote">Buehler 等人 2020 年的「小数据市场模拟器」用签名把有限历史映成情景族，动机正是对冲训练需要的状态空间覆盖。生成器的降维选择直接决定对冲网络能学到什么——丢掉的维度，恰好可能是对冲要用的维度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>账本级策略：共享权重的递归网络，每步输入因果特征——各工具库存、已实现波动、<a href="/quant/path-signature-features">路径摘要</a>、离关键位障碍的距离；输出是对每个对冲工具的调仓，过投影执行限额。对照基线按层排：BS delta 与<a href="/quant/discrete-hedge-error">离散对冲误差</a>的量化、<a href="/quant/delta-hedge-freq">对冲频率</a>的效应、桶方法的实际历史残差——深度对冲必须在这些之上按对冲误差的分布（分位数与尾部）交卷，均值改进没有说服力。模拟器来自上一课的冻结交付；训练前再做一轮检查：模拟器覆盖的机制——波动聚集、跳跃、基差联动——是否包含账本的真实风险源，缺哪一项，策略就会在那一项上开出虚假的便宜。</p>',4)),(E(),r(o,null,{default:e(()=>[A(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIM%5B%22%E5%86%BB%E7%BB%93%E6%A8%A1%E6%8B%9F%E5%99%A8%22%5D%20--%3E%20ENV%5B%22%E8%B4%A6%E6%88%B7%EF%BC%9A%E5%A4%9A%E5%B7%A5%E5%85%B7%E5%BA%93%E5%AD%98%20%2B%20%E6%91%A9%E6%93%A6%20%2B%20%E9%99%90%E9%A2%9D%22%5D%0A%20%20F%5B%22%E5%9B%A0%E6%9E%9C%E7%89%B9%E5%BE%81%20%2F%20%E8%B7%AF%E5%BE%84%E6%91%98%E8%A6%81%22%5D%20--%3E%20NET%5B%22%E9%80%92%E5%BD%92%E7%AD%96%E7%95%A5%E7%BD%91%E7%BB%9C%22%5D%0A%20%20NET%20--%3E%20TR%5B%22%E5%A4%9A%E5%B7%A5%E5%85%B7%E8%B0%83%E4%BB%93%EF%BC%8C%E8%BF%87%E6%8A%95%E5%BD%B1%22%5D%0A%20%20TR%20--%3E%20ENV%0A%20%20ENV%20--%3E%20PL%5B%22%E7%BB%88%E7%AB%AF%E6%8D%9F%E7%9B%8A%20PL%22%5D%0A%20%20PL%20--%3E%20RHO%5B%22%E5%87%B8%E9%A3%8E%E9%99%A9%E5%BA%A6%E9%87%8F%20%CF%81%EF%BC%9ACVaR%20%E6%88%96%E7%86%B5%22%5D%0A%20%20RHO%20--%3E%20NET%0A%20%20B%5B%22delta%20%2F%20%E7%A6%BB%E6%95%A3%E8%AF%AF%E5%B7%AE%20%2F%20%E6%A1%B6%E6%96%B9%E6%B3%95%E5%9F%BA%E7%BA%BF%22%5D%20--%3E%20EV%5B%22%E5%AF%B9%E5%86%B2%E8%AF%AF%E5%B7%AE%E5%88%86%E5%B8%83%E5%AF%B9%E7%85%A7%22%5D%0A%20%20ENV%20--%3E%20EV%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多工具下的机制性风险：网络把对冲搬到模拟器里最便宜的工具上，若那份便宜来自错误校准的基差，真实账上就会爆——工具的模拟必须与现货联合校准，这是骨架课的警告在账本级的放大。无交易区从单一工具扩展成逐工具的带状结构，带与带之间通过库存耦合：一只工具的再平衡改变其余工具的状态，网络吃全状态就能表达，吃部分状态就学不出。数据驱动模拟器的小数据问题在此变成对冲问题：降维要按对冲任务的残差验收，不按生成质量验收——生成得像，不等于残差里没有漏掉的风险。</p><p><span class="marginnote">常见误区：容易以为网络「挑了便宜的工具」说明它聪明；若那份便宜来自模拟器里错误校准的基差，真实市场上根本没有这份便宜——先审模拟器，再夸策略。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>报告与训练分层：监管与限额仍说希腊的语言，报告层单独算希腊并接受它不满足经典 PDE 恒等式；训练层不把报告公式写回损失。\\(\\rho\\) 在上线前与销售、资本口径一起钉死，训后调整 \\(\\rho\\) 等于换产品。再训练与漂移是下一课的治理对象；本课的边界是：整本账的深度对冲不消灭桶方法——桶仍是最好的挑战者与对照语言。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>深化三问：整本账、对冲工具集、\\(\\rho\\) 的产品属性；桶方法降级为挑战者与对照。</li><li>CVaR 的 \\(\\alpha\\)、熵的 \\(\\eta\\) 是产品定义，调整即换产品，残差不可比。</li><li>对冲误差按分布交卷；工具变便宜先查基差校准，再信策略。</li><li>模拟器的降维按对冲任务验收：生成得像不等于对冲可用。</li><li>出处：Buehler, Gonon, Teichmann and Wood, <em>QF</em>, 2019；Buehler, Horvath, Lyons, Perez Arribas and Wood, 2020；Kolm and Ritter, <em>Quantitative Finance</em>, 2019。</li></ul>',7))])}const F=i(s,[["render",h]]);export{C as __pageData,F as default};
